package dev.plattnericus.pokyh.ui.theme

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * The app's single icon family: **Phosphor Icons** (MIT, phosphoricons.com), vendored as
 * [ImageVector] path data rather than pulled in as a dependency or as `res/drawable` XML.
 *
 * Why vendored as Kotlin: every icon stays a plain `val` (a `res` vector would need a
 * `@Composable` `vectorResource()` read at each use site, which would force ~a dozen plain
 * helper functions in the screens to become composable), the set is tree-shaken by R8 like any
 * other code, and there is no second icon library on the classpath to accidentally import from.
 *
 * Every glyph here is a single path on the same 256x256 grid with the same optical weight, so
 * icons always look like siblings — the whole point of replacing the previous mix of
 * `Icons.Filled` / `Icons.Outlined` / `Icons.AutoMirrored` Material glyphs.
 *
 * Two weights only, and each has ONE job (see [PokyhIcons] for the rule):
 *   - [Ph] regular  -> everything
 *   - [PhFill] fill -> selected nav tab, status badges, rating stars
 *
 * Generated — do not hand-edit path data. To add an icon, take the `d` attribute of
 * `@phosphor-icons/core@2/assets/{regular,fill}/<name>.svg` and add an entry.
 */
private fun phosphor(name: String, pathData: String): ImageVector = ImageVector.Builder(
    name = name,
    defaultWidth = 24.dp,
    defaultHeight = 24.dp,
    viewportWidth = 256f,
    viewportHeight = 256f,
).apply {
    addPath(pathData = PathParser().parsePathString(pathData).toNodes(), fill = SolidColor(Color.Black))
}.build()

